package org.jsoup.nodes;

import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.jsoup.helper.Validate;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class XmlDeclaration_getWholeDeclaration_TriageGen1Test {

    /**
     * Helper method to inject attributes into the private field of XmlDeclaration
     * since the provided constructor doesn't show an attributes setter.
     */
    private void setAttributes(XmlDeclaration decl, Map<String, String> attributes) throws Exception {
        Field field = XmlDeclaration.class.getDeclaredField("attributes");
        field.setAccessible(true);
        field.set(decl, attributes);
    }

    @Test
    public void testGetWholeDeclaration_NameNotXml() {
        // Test case: name is not "xml" -> should return name
        XmlDeclaration decl = new XmlDeclaration("html", "http://example.com", false);
        assertEquals("html", decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlButAttributesSizeTooSmall() throws Exception {
        // Test case: name is "xml" but attributes size <= 1 -> should return name
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", "1.0");
        setAttributes(decl, attributes);

        // The logic: if(decl.equals("xml") && attributes.size() > 1)
        // Here size is 1, so it should hit the 'else' branch.
        assertEquals("xml", decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithBothVersionAndEncoding() throws Exception {
        // Test case: name is "xml", attributes size > 1, has both version and encoding
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", "1.0");
        attributes.put("encoding", "UTF-8");
        attributes.put("extra", "dummy"); // Ensure size > 1
        setAttributes(decl, attributes);

        String expected = "xml version=\"1.0\" encoding=\"UTF-8\"";
        assertEquals(expected, decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithVersionOnly() throws Exception {
        // Test case: name is "xml", size > 1, has version but encoding is null
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", "1.0");
        attributes.put("other", "value"); // Ensure size > 1
        attributes.put("encoding", null); 
        setAttributes(decl, attributes);

        String expected = "xml version=\"1.0\"";
        assertEquals(expected, decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithEncodingOnly() throws Exception {
        // Test case: name is "xml", size > 1, version is null but encoding is present
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", null);
        attributes.put("encoding", "UTF-8");
        attributes.put("other", "value"); // Ensure size > 1
        setAttributes(decl, attributes);

        String expected = "xml encoding=\"UTF-8\"";
        assertEquals(expected, decl.getWholeDeclaration());
    }

    @Test
    public void testGetWholeDeclaration_XmlWithNeither() throws Exception {
        // Test case: name is "xml", size > 1, both version and encoding are null
        XmlDeclaration decl = new XmlDeclaration("xml", "http://example.com", false);
        Map<String, String> attributes = new HashMap<>();
        attributes.put("version", null);
        attributes.put("encoding", null);
        attributes.put("other", "value"); // Ensure size > 1
        setAttributes(decl, attributes);

        // StringBuilder starts with "xml", no appends happen
        assertEquals("xml", decl.getWholeDeclaration());
    }
}
